INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5491fc50-5b1c-4dec-b494-0ac311be9c4e', '21feff02-016d-46e2-bb9d-c27495133b1b', '91. óra: Feladatmegoldás', 'Hétköznapi vásárlási, méréseket és egyenleteket tartalmazó szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "8d3e9170-7a76-4483-919c-5582ebe53fdd", "text": "3 füzet és 1 toll összesen 1100 Ft-ba kerül. A toll ára 200 Ft. Hány Ft 1 füzet ára? (3x + 200 = 1100 -> 3x = 900)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "6631bb17-4439-41fa-b4b9-c20047effd6f", "text": "Peti 2000 Ft-tal ment a boltba. Vett 3 kg narancsot 500 Ft/kg áron. Hány Ft visszajárót kapott? (2000 - 1500)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "ed08c1db-995b-4ea5-a927-5113ccdaf187", "text": "Egy raktárban 120 láda gyümölcs van. Az első nap elvitték a 1/3-át, a második nap a megmaradt ládák felét. Hány láda maradt? (120 - 40 = 80, 80 - 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "a062f290-be5d-4b8a-8f59-a0d7aeef2abf", "text": "A mindennapi életben sok probléma modellezhető egyenlettel.", "type": "true-false", "options": [{"id": "76320d06-26b2-4300-a05e-87d556215853", "text": "Igaz", "isCorrect": true}, {"id": "0eac844f-3859-44be-b1aa-c1010ff3f582", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ebe11d66-b9bc-4508-87d2-a19c43ca6e0e", "text": "Melyik egyenlet írja le: ''Egy szám 4-szeresénél 5-tel több a 25''? (4x + 5 = 25)", "type": "multiple-choice", "options": [{"id": "c81c2be5-5143-4d7b-9f91-6c0374286cc9", "text": "4x + 5 = 25", "isCorrect": true}, {"id": "d66001b1-28df-4c94-8d24-1fbad53f3565", "text": "x + 4 + 5 = 25", "isCorrect": false}, {"id": "62b64b47-2594-4919-9e05-d4c8cad1e1a7", "text": "4x - 5 = 25", "isCorrect": false}, {"id": "117f50f9-50e7-4628-874c-5082cc5c39d2", "text": "x / 4 + 5 = 25", "isCorrect": false}], "timeLimit": 15}, {"id": "f033e355-0eda-41f5-84eb-38f9c290f25a", "text": "Mennyi a gondolt szám a 4x + 5 = 25 egyenletben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "175cb719-70c4-4e28-a47c-c020ca440501", "text": "Az ellenőrzést a feladat eredeti szövegébe való behelyettesítéssel végezzük.", "type": "true-false", "options": [{"id": "4f0270e9-7503-4317-95c2-6e05029f7b05", "text": "Igaz", "isCorrect": true}, {"id": "000464f7-4d4c-4010-8bc0-9cb3d984dd7f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('70593005-66bb-4101-9569-a497db7ffdd9', '21feff02-016d-46e2-bb9d-c27495133b1b', '92. óra: Több megoldás is lehet', 'Több megoldást megengedő szöveges feladatok és egyenlőtlenségek vizsgálata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "733adcc3-0b2b-4b18-a577-25d95b45609e", "text": "Katinak legfeljebb 10 Ft-ja lehet, és páros számú forintja van. Hányféle lehetséges összege lehet természetes számokban? (0, 2, 4, 6, 8, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "86bf5b05-0afb-4a89-bd90-212c418eaed0", "text": "Mely kifejezés jelenti azt, hogy ''legfeljebb 5''?", "type": "multiple-choice", "options": [{"id": "012f3510-beb6-4eb9-b132-142c1ce6d2a4", "text": "Kisebb vagy egyenlő, mint 5 (x <= 5)", "isCorrect": true}, {"id": "73019520-82b5-47d1-ae5f-6e7d86617bfb", "text": "Nagyobb, mint 5", "isCorrect": false}, {"id": "77606f45-fa28-4cea-b010-0c7f870a9d86", "text": "Pontosan 5", "isCorrect": false}, {"id": "fe5f6213-6085-450e-b373-d3a6cb702fb5", "text": "Legalább 5", "isCorrect": false}], "timeLimit": 15}, {"id": "9d0ceb93-98c3-4fc7-9d94-e060dca5e001", "text": "Mely kifejezés jelenti azt, hogy ''legalább 5''?", "type": "multiple-choice", "options": [{"id": "d712c4f2-e443-4167-8a39-35ff485ef12e", "text": "Nagyobb vagy egyenlő, mint 5 (x >= 5)", "isCorrect": true}, {"id": "f12939fb-a25d-427a-8bde-8cc5ce1c67b5", "text": "Kisebb, mint 5", "isCorrect": false}, {"id": "a2f3a847-ffe3-47a5-9458-5f3fd144d3a2", "text": "Pontosan 5", "isCorrect": false}, {"id": "6c7226da-b350-4797-84c1-cdb665eb3a51", "text": "Legfeljebb 5", "isCorrect": false}], "timeLimit": 15}, {"id": "dcf48ec9-f25d-4204-b4ac-6d61d28aa7c0", "text": "A ''legalább 3 és legfeljebb 6'' feltételnek eleget tevő egész számok száma: 3, 4, 5, 6 (összesen 4 szám).", "type": "true-false", "options": [{"id": "6557f2cc-2881-4d3d-9d73-74a9d169d04f", "text": "Igaz", "isCorrect": true}, {"id": "ee8f6116-0e4e-4ce9-b39c-61ee7e052938", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "149fff05-2990-42c7-98dd-9edec7382af0", "text": "Hány természetes szám megoldása van a 2 * x <= 8 egyenlőtlenségnek? (x = 0, 1, 2, 3, 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "c3a32996-e399-48c8-822c-81d67a14de08", "text": "A több megoldással rendelkező feladatoknál az összes megoldás megtalálása a cél.", "type": "true-false", "options": [{"id": "85dff7a8-e88b-4965-9834-c0b41cf5146a", "text": "Igaz", "isCorrect": true}, {"id": "9fae6e73-7642-44b0-81cd-6753c71322e5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ec8cbffd-ae5f-4a79-94dd-5e9476c65e3f", "text": "Melyik legkisebb természetes szám teljesíti az x > 7 egyenlőtlenséget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('86a11976-05a2-4fda-9fe5-5eee367796e0', '21feff02-016d-46e2-bb9d-c27495133b1b', '93. óra: Létraverseny II.', 'Versenyszerű feladatmegoldás páros munkában a százalék és szöveges feladatok témakörében.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "1d155f96-6c86-4d7a-b336-619122d45ce0", "text": "Mennyi 1000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "dec5f41e-feba-4691-a454-8432c71a28ad", "text": "Melyik szám teszi igazzá: 2 * x + 10 = 50?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "57a3bca5-f4a5-43e9-a9ef-6194d597dfc5", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 5 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "baa47323-bd4d-40d3-be31-308327073cc2", "text": "Hány százalék felel meg a 3/5 törtnek? (3/5 = 60/100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "57305e2f-7293-41e3-8e8a-e00e421cd8ee", "text": "Gondoltam egy számot, elosztottam 3-mal, hozzáadtam 4-et és 10-et kaptam. Mi a szám? ((10-4)*3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "dc59c639-7838-4d4b-899d-e7c9491f8ad4", "text": "A játékos feladványok erősítik az osztály közösségét és a matematikai önbizalmat.", "type": "true-false", "options": [{"id": "55fd9c16-be1c-4ec8-904f-acf667c0264f", "text": "Igaz", "isCorrect": true}, {"id": "4a65337d-e56e-4266-a0bf-94c0e56feed7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "39a69e2c-7ec9-4cda-b1f4-ede587c7ba7d", "text": "Mennyi 400-nak a 25%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('228df88c-dfd2-4f04-be74-7d176ff52882', '21feff02-016d-46e2-bb9d-c27495133b1b', '94. óra: Összefoglalás', 'A fejezet fogalmainak (arány, egyenes arányosság, százalék, nyitott mondatok) összefoglalása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "1a3e45a1-951f-48d4-bdd0-a85c0a79e91c", "text": "Mennyi a 8 : 24 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "fae1620d-9454-4db9-9f89-300d6ba3fcc9", "text": "1 : 3", "isCorrect": true}, {"id": "fc848702-cfdb-449f-b02f-79777b3bd16c", "text": "1 : 4", "isCorrect": false}, {"id": "e075cd16-535c-4a57-992b-86322bf04047", "text": "2 : 3", "isCorrect": false}, {"id": "7d979d2b-f5bc-48d3-be4d-b1ecca3bceac", "text": "3 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "c9f4933c-818e-4132-92fe-26abd1d1ba41", "text": "Hány százalék felel meg a 1/2-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "1ea8cd24-e4d6-462f-9adc-83462e2e5cda", "text": "Hány százalék felel meg a 1/5-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "f48494e0-ffc5-4e27-b143-e8da78ddd26e", "text": "Mennyi 600 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "6d8fb64e-4f63-4512-be05-46e5630ea5e4", "text": "Melyik szám teszi igazzá: 4 * x - 8 = 32? (40/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "5bda17ed-2374-44eb-9c0e-1aa75f4b7329", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "e291824f-e417-491e-8e7f-5bb1575ac6e0", "text": "Igaz", "isCorrect": true}, {"id": "268301ef-8aff-410c-a127-6459bb6f0d00", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6b4339d2-d39e-4584-b399-7bb50cb6291c", "text": "Mennyi 150-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bc4f217d-83b6-45b4-8165-e895eed41334', '21feff02-016d-46e2-bb9d-c27495133b1b', '95. óra: Gyakorlóóra', 'Gyakorló feladatok önállóan, becslés és ellenőrzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "aebd6d27-da3d-41da-b66c-be265b3d2849", "text": "Egy 8000 Ft-os táska ára 25%-kal csökkent. Hány Ft a kedvezmény? (8000 * 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "fde79b42-1ece-499d-86c1-f2c368adad59", "text": "Mennyi a táska új ára? (8000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6000"}, {"id": "b7b6c291-fb3c-446a-a1d7-7ef83638f8a7", "text": "Melyik szám teszi igazzá: (x + 4) : 5 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "26"}, {"id": "b4c97227-e8a6-44ed-939c-c5e16a9f20c2", "text": "Ha 4 kg alma 1600 Ft, egyenes arányosság esetén 7 kg alma 2800 Ft-ba kerül.", "type": "true-false", "options": [{"id": "e2deccd0-8127-4e8b-b257-6f5a4c5503b2", "text": "Igaz", "isCorrect": true}, {"id": "1a932388-f89c-4739-b959-f482636980c2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "20d3c9ca-0b91-44e8-a9b0-fec4e054a55b", "text": "Mennyi 50-nek a 120%-a? (50 * 1,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "4a473c36-b33b-4582-ac56-7a351a8acb78", "text": "Az ellenőrzés mindig megnyugtató visszajelzést ad a feladat helyességéről.", "type": "true-false", "options": [{"id": "8d7f3d6b-aa93-4fc6-afcc-f2f380ad0db1", "text": "Igaz", "isCorrect": true}, {"id": "d4c2bd7f-6e99-4528-89bc-9da57a86c243", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c909f7e1-27b0-491f-8133-6d2d1a427a24", "text": "Mennyi 1000-nek az 1%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3c301b9d-0f16-43ee-8f73-0ce55ee5db90', '21feff02-016d-46e2-bb9d-c27495133b1b', '96. óra: Témazáró dolgozat', 'Témazáró számonkérés az Arány, százalék, szöveges feladatok témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "5696a374-b031-4cae-9080-049521bcb2b2", "text": "1. Mennyi a 10 : 35 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "a036d479-6772-4ab1-bd87-30a21af35b2b", "text": "2 : 7", "isCorrect": true}, {"id": "3a38ea15-fa58-4995-a629-d812ce9c186b", "text": "1 : 35", "isCorrect": false}, {"id": "05f16c4f-f0c3-45ff-9b07-83bd19b29286", "text": "2 : 5", "isCorrect": false}, {"id": "6df02229-89d5-41f6-afc6-a20c7400cb18", "text": "5 : 7", "isCorrect": false}], "timeLimit": 15}, {"id": "eac174b8-6014-44dd-abd4-c9a63d36fc50", "text": "2. Ossz el 600 Ft-ot 1 : 2 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "59dbcdb3-2841-408c-b1a3-435e4552d7b1", "text": "3. Ha 3 kg narancs 1500 Ft, mennyibe kerül 4 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "5f38bc8e-aad8-4a3f-861f-2d0cc2e2b235", "text": "4. Hány százalék felel meg a 3/4 törtszámnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "f523afec-45a4-4d83-8838-e9f14387d487", "text": "5. Mennyi 4000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}, {"id": "1445a4dd-1c75-40e3-9fc2-64a53339c92a", "text": "6. Melyik szám teszi igazzá: 3 * x + 8 = 35?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "8c8f819b-8661-4f6c-9976-ff657e610653", "text": "7. Gondoltam egy számot, elosztottam 2-vel, kivontam belőle 5-öt, 10-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "37975147-9d4a-43cf-94af-897cb647044b", "text": "8. Mennyi 200-nak a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "8b8c33a5-05a0-4c06-8129-9040e873689a", "text": "9. Az egyenes arányosság esetén a két mennyiség hányadosa állandó.", "type": "true-false", "options": [{"id": "306d03ae-c451-447b-bf98-db95c821dc20", "text": "Igaz", "isCorrect": true}, {"id": "f923d389-280a-44ea-b103-4e8825993a62", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7eaeca12-fa64-427c-993b-0f716fe65dda", "text": "10. Egy 5000 Ft-os nadrág ára 10%-kal nőtt. Mennyi az új ár? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5500"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('23733658-ff2a-459c-930a-c74692465e32', '21feff02-016d-46e2-bb9d-c27495133b1b', '97. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat feladatainak megbeszélése, hibajavítás és összegzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "549005bf-ae7d-45a3-b9fc-1104550dc0f1", "text": "Mi volt a legfontosabb tapasztalat a százalékszámítási feladatoknál?", "type": "multiple-choice", "options": [{"id": "13704781-d4f0-4c0e-97dc-1fc81bf2e123", "text": "Az 1% kiszámítása vagy a törtalakkal való szorzás biztonságos számolást ad", "isCorrect": true}, {"id": "a5ceb4a9-2129-4c1b-b240-195fbc512edd", "text": "A százalékjel elhagyása", "isCorrect": false}, {"id": "cfd7508d-580e-421e-baec-e7aa51ac9c43", "text": "Mindig 100-at kell válaszolni", "isCorrect": false}, {"id": "e8ca5dbb-a71d-425c-8a05-f35a2880c9c9", "text": "Nem kell kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "fa0be997-3d5d-43ed-a86c-912350db3fbf", "text": "Az arányos osztásnál az arányszámok összege adja meg a részek számát.", "type": "true-false", "options": [{"id": "15f13218-072e-4831-b6d0-7096dd3f3ca5", "text": "Igaz", "isCorrect": true}, {"id": "065c4d11-7629-4df5-b0a7-b5a14aea97e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "59fc69a3-a26f-4fc1-891c-760ee6918139", "text": "Mennyi 2000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "5d08eb63-0166-43db-8c67-5666b7d7f603", "text": "Melyik szám teszi igazzá: 5 * x - 10 = 40?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "314c7a08-c942-4699-be05-88b81c7090c3", "text": "A hibák elemzése segít a sikeresbb jövőbeli teljesítményben.", "type": "true-false", "options": [{"id": "5d82dddb-1c63-4ccd-b892-d283bb067332", "text": "Igaz", "isCorrect": true}, {"id": "c5c309d5-19d9-43f7-8a03-650edb2e748a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "27f4c6c1-b045-407a-a46f-35c0b5e52a36", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "d96ea783-6363-433d-b3cf-792fd68990cb", "text": "Hány százalék felel meg az 1/10-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6532d024-9795-414a-b3ed-a3277ab1ffa3', '21feff02-016d-46e2-bb9d-c27495133b1b', '98. óra: Hosszúság, tömeg, idő', 'A hosszúság, tömeg és idő mérésének ismétlése, mértékegységek és átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "cfcd96a9-9aa0-4550-88f3-6b2b9dcea80a", "text": "Hány milliméter 1 méter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "41ab5083-bee8-4fd7-86ec-e067c307d2f5", "text": "Hány dekagramm (dkg) 1 kilogramm (kg)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "cc119155-e676-43ef-9eb2-66ab568ef1c5", "text": "Hány másodperc van 1 órában? (60 * 60)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3600"}, {"id": "c7708237-f373-47fe-8bea-1272dc891dd0", "text": "Mennyi 2,5 km méterben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "267f3804-3037-4be0-ac3a-2bbe77be606f", "text": "Hány kilogramm 3,5 tonna?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}, {"id": "2a94e223-3e8e-4e4f-97c7-d05a4d1b7c16", "text": "Az időváltás 60-as alapon működik a másodperc, perc és óra között.", "type": "true-false", "options": [{"id": "bd5c888d-154b-4007-9912-eca40d7cb9d4", "text": "Igaz", "isCorrect": true}, {"id": "4a12e51f-7a46-4da1-94cc-18b09f0863ed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "41341193-4237-4d77-99c6-2c50895ef469", "text": "Hány perc 2 óra 15 perc?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "135"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6968f83b-1813-4d1d-97e2-ee0456e977e3', '21feff02-016d-46e2-bb9d-c27495133b1b', '99. óra: Hosszúság, tömeg, idő II.', 'Összetett mértékegység-átváltási feladatok és gyakorlás.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "7acaf525-93b6-45bc-9a46-918e0ab397fb", "text": "Hány cm van 4,5 m-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "450"}, {"id": "96ed47a8-13dc-4515-9e18-9aef18c69cc7", "text": "Hány gramm 0,75 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "750"}, {"id": "cf2ff89d-93f1-4974-b11b-32129f479e21", "text": "Hány napból áll 4 hét?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "d0a5a01a-e9a0-4e3b-8b4a-0b17225f38e3", "text": "A 1500 m megegyezik 1,5 km-rel.", "type": "true-false", "options": [{"id": "812e23e2-bd1b-46a6-84fa-23906bf13ca5", "text": "Igaz", "isCorrect": true}, {"id": "5cf4dfad-94ac-4c57-8c41-9920d118bb07", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3129d957-7cf2-42ca-a721-782f93a76730", "text": "Mennyi 500 dkg kg-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "5aad754e-a5ed-4cea-aa8a-bc1f2b1372bb", "text": "Hány perc 1 nap negyede (6 óra)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "4d6d9177-a530-435d-9c7e-e9388a7b29e5", "text": "A nagyobb mértékegységből kisebb felé haladva szorzunk a váltószámmal.", "type": "true-false", "options": [{"id": "08e6feb8-9fca-462b-9dd6-c95633156f0f", "text": "Igaz", "isCorrect": true}, {"id": "aa37f441-e802-45ce-8b06-691d35fd2e2e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('886b3b68-a5bb-48f3-8d9f-0ad278a81640', '21feff02-016d-46e2-bb9d-c27495133b1b', '100. óra: A sokszögek kerülete', 'Négyzet, téglalap, háromszög és sokszögek kerületének számítása (K).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "4048897c-6ab4-41d9-904e-c1ed27c6c867", "text": "Mi a téglalap kerületének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "5a17dbdb-a054-40bf-83fe-1d15877629dd", "text": "K = 2 * (a + b)", "isCorrect": true}, {"id": "38c2ccb7-c682-4892-83ac-7fe983e3332d", "text": "K = a * b", "isCorrect": false}, {"id": "3b960d75-0c6b-4119-9d1a-3cdf6fd25c45", "text": "K = a + b", "isCorrect": false}, {"id": "58078aa9-750e-4b26-8922-448bd3c6b7b4", "text": "K = 4 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "6cfc52aa-067a-4ed7-a357-fbc3e7495390", "text": "Mi a négyzet kerületének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "1bc502a6-472b-475c-b54a-e0b31e3436dc", "text": "K = 4 * a", "isCorrect": true}, {"id": "2cce4c00-ae0f-463b-a99c-0f02be998276", "text": "K = a * a", "isCorrect": false}, {"id": "a696b1bc-e433-4661-91e8-21deb623c4a8", "text": "K = 2 * a", "isCorrect": false}, {"id": "b7f4b252-2a1e-4b4a-985b-415c25a6a59b", "text": "K = 6 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "0b73d859-d800-459a-ac45-a1917d726ce4", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap kerülete? (2 * (6 + 8))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "0de3bdf7-1b1c-444f-b7b4-bb4087ba32da", "text": "Mennyi a 7 cm oldalú négyzet kerülete? (4 * 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "30959c54-5c8e-4f3d-a2a5-aed138bb8fa5", "text": "Mennyi a 3 cm, 4 cm, 5 cm oldalú háromszög kerülete? (3+4+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "26fe9c5d-77c4-4780-b05f-69b96fccfcb4", "text": "A kerület a sokszöget határoló oldalak hosszának összege.", "type": "true-false", "options": [{"id": "db652871-7b6f-4867-80ae-bc499d9392f9", "text": "Igaz", "isCorrect": true}, {"id": "e7eb4695-55b2-41da-8f32-3dfbaf25d6bf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fddf461f-e75f-4a23-8f5b-4472577a54d8", "text": "Mennyi a 5 cm oldalú szabályos ötszög kerülete? (5 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;